// ../case-tool/src/utils/case-document.ts
var CASE_SCHEMA_VERSION = "30.0.0";
var CASE_PLAN_FILENAME = "caseplan.json";
function buildMinimalCaseDocument(options) {
  return {
    id: prefixedId("case-", 10),
    name: options.name,
    version: CASE_SCHEMA_VERSION,
    ...options.description !== undefined && {
      description: options.description
    },
    bindings: [],
    variables: { inputOutputs: [] },
    metadata: {
      caseIdentifier: options.caseIdentifier ?? options.name,
      caseAppEnabled: options.caseAppEnabled ?? false,
      caseIdentifierType: options.identifierType ?? "constant",
      publishVersion: 2
    },
    nodes: [
      {
        id: DEFAULT_TRIGGER_ID,
        type: "uipath.case.trigger",
        data: {
          typeVersion: "1.0.0",
          display: { label: DEFAULT_TRIGGER_LABEL },
          inputs: { serviceType: "None" }
        }
      }
    ],
    edges: []
  };
}

