var initCaseProject = async (name, options) => {
  if (!VALID_PROJECT_NAME_REGEX.test(name)) {
    throw new Error(`Invalid project name "${name}". Name can only contain letters, numbers, underscores (_), and hyphens (-).`);
  }
  const fs = getFileSystem();
  const { prepareProjectLocation, tryRegisterProjectInParentSolution } = await import("./index-hfsfzg4k.js");
  const { projectDir, autoCreatedSolution } = await prepareProjectLocation(fs, fs.path.resolve(name), name, { skipRegistration: options.skipSolutionRegistration === true });
  const projectDirExists = await fs.stat(projectDir).then(() => true).catch((err) => {
    const code = err instanceof Error ? err.code : undefined;
    if (code === "ENOENT" || code === "PathNotFound") {
      return false;
    }
    throw err;
  });
  if (projectDirExists && !options.force) {
    const existingEntries = await fs.readdir(projectDir);
    if (existingEntries.length > 0) {
      throw new Error(`Directory "${name}" already exists and is not empty. Use --force to overwrite.`);
    }
  }
  const safeMkdir = async (dir) => {
    const [mkdirError] = await catchError(fs.mkdir(dir));
    if (mkdirError) {
      const code = mkdirError.code;
      if (code !== "EEXIST") {
        throw mkdirError;
      }
    }
  };
  await safeMkdir(projectDir);
  const projectId = crypto.randomUUID();
  const operateJson = {
    $schema: "https://cloud.uipath.com/draft/2024-12/operate",
    projectId,
    contentType: "CaseManagement",
    targetFramework: "Portable",
    runtimeOptions: {
      requiresUserInteraction: false,
      isAttended: false
    }
  };
  const entryPointsJson = {
    $schema: "https://cloud.uipath.com/draft/2024-12/entry-point",
    $id: "entry-points.json",
    entryPoints: [
      {
        filePath: `/content/caseplan.json.bpmn#${DEFAULT_TRIGGER_ID}`,
        uniqueId: crypto.randomUUID(),
        type: "CaseManagement",
        input: {
          type: "object",
          properties: {}
        },
        output: {
          type: "object",
          properties: {}
        },
        displayName: DEFAULT_TRIGGER_LABEL
      }
    ]
  };
  const bindingsJson = {
    version: "2.0",
    resources: []
  };
  const packageDescriptorJson = {
    $schema: "https://cloud.uipath.com/draft/2024-12/package-descriptor",
    files: {
      "operate.json": "content/operate.json",
      "entry-points.json": "content/entry-points.json",
      "bindings.json": "content/bindings_v2.json",
      "caseplan.json": "content/caseplan.json",
      "caseplan.json.bpmn": "content/caseplan.json.bpmn"
    }
  };
  const projectUiproj = {
    Name: name,
    ProjectType: "CaseManagement"
  };
  await fs.writeFile(fs.path.join(projectDir, "project.uiproj"), `${JSON.stringify(projectUiproj, null, 2)}
`);
  await fs.writeFile(fs.path.join(projectDir, "operate.json"), `${JSON.stringify(operateJson, null, 2)}
`);
  await fs.writeFile(fs.path.join(projectDir, "entry-points.json"), `${JSON.stringify(entryPointsJson, null, 2)}
`);
  await fs.writeFile(fs.path.join(projectDir, "bindings_v2.json"), `${JSON.stringify(bindingsJson, null, 2)}
`);
  await fs.writeFile(fs.path.join(projectDir, "package-descriptor.json"), `${JSON.stringify(packageDescriptorJson, null, 2)}
`);
  const casePlanPath = fs.path.join(projectDir, CASE_PLAN_FILENAME);
  const casePlanExists = await fs.exists(casePlanPath);
  if (!casePlanExists) {
    await fs.writeFile(casePlanPath, `${JSON.stringify(buildMinimalCaseDocument({ name }), null, 4)}
`);
  }
  const solutionRegistration = await tryRegisterProjectInParentSolution(fs, projectDir, { skipRegistration: options.skipSolutionRegistration === true });
  let projectArtifacts;
  if ((solutionRegistration.Status === "Registered" || solutionRegistration.Status === "AlreadyRegistered") && solutionRegistration.Solution && solutionRegistration.ProjectId) {
    const { ensureProjectArtifacts } = await import("./project-artifacts-9z7atbk7.js");
    projectArtifacts = await ensureProjectArtifacts({
      solutionDir: fs.path.dirname(solutionRegistration.Solution),
      projectId: solutionRegistration.ProjectId,
      projectName: name,
      projectType: "CaseManagement"
    });
  }
  const data = {
    Status: "Created successfully",
    Path: projectDir,
    CasePlan: casePlanPath,
    CasePlanStatus: casePlanExists ? "Preserved" : "Created",
    SolutionRegistration: solutionRegistration
  };
  if (autoCreatedSolution) {
    data.AutoCreatedSolution = autoCreatedSolution;
  }
  if (projectArtifacts) {
    data.ProjectArtifacts = projectArtifacts;
  }
  if (solutionRegistration.Instructions) {
    data.NextSteps = solutionRegistration.Instructions;
  }
  OutputFormatter.success({
    Result: RESULTS.Success,
    Code: "CaseInit",
    Data: data
  });
};
