// ../case-tool/src/utils/case-schema-error.ts
var DETECTION_FAILURE_MARKERS = [
  "is not a valid Case Management JSON of any previous version",
  "is not a valid Case Management JSON of any known version"
];
var AUTHORING_GUIDANCE = "Author caseplan.json directly, then run `uip maestro case validate <file>`. " + "The task and stage JSON shapes are documented in the uipath-maestro-case " + "skill under references/plugins/ — load it rather than inferring the shape " + "from packed output.";
var DETECTION_FAILURE_INSTRUCTIONS = [
  "The case plan did not match any schema version bundled with this CLI.",
  "",
  "This usually means a version mismatch rather than a corrupt file. Check the",
  "`version` field at the root of caseplan.json: a plan opened and saved in",
  "Studio Web is upgraded in place and may declare a NEWER version than this",
  "CLI accepts, in which case upgrading the CLI is the fix. Note the wording of",
  'the underlying error — "any previous version" is misleading here, since the',
  "usual cause is a plan that is newer, not older.",
  "",
  "If the version is in range, the document is structurally invalid against that",
  "schema. Re-run `uip maestro case validate <file>` — validate reports per-node",
  "paths and the accepted values for a field, which `pack` does not.",
  "",
  AUTHORING_GUIDANCE
].join(`
`);
function isCaseSchemaDetectionFailure(error) {
  const message = error instanceof Error ? error.message : String(error ?? "");
  return DETECTION_FAILURE_MARKERS.some((marker) => message.includes(marker));
}
function enrichCaseSchemaError(error) {
  const message = error instanceof Error ? error.message : String(error ?? "");
  if (!isCaseSchemaDetectionFailure(error)) {
    return message;
  }
  return `${DETECTION_FAILURE_INSTRUCTIONS}

Original error: ${message}`;
}

