var DIRECT_EDIT_REPLACEMENT = "Edit caseplan.json directly, then run `uip maestro case validate <file>`." + " See the uipath-maestro-case skill (references/plugins/) for the stage and task JSON shapes.";
var EDGE_REPLACEMENT = "Keep caseplan.json edges as []; model transitions with stage entry/exit conditions, then run `uip maestro case validate <file>`." + " See the uipath-maestro-case skill (references/plugins/) for the stage and task JSON shapes.";
function findCommand(program, commandParts) {
  let parent = program;
  for (const part of commandParts) {
    const command = parent.commands.find((candidate) => candidate.name() === part);
    if (!command)
      return;
    parent = command;
  }
  return parent;
}
function replacementFor(commandParts) {
  if (commandParts[0] === "edges") {
    return EDGE_REPLACEMENT;
  }
  return DIRECT_EDIT_REPLACEMENT;
}
function deprecateCaseAuthoringMutators(program) {
  for (const commandParts of DEPRECATED_CASE_AUTHORING_MUTATORS) {
    const commandName = commandParts.join(" ");
    const command = findCommand(program, commandParts);
    if (!command) {
      throw new Error(`Cannot deprecate missing case command: ${commandName}`);
    }
    command.registeredArguments.length = 0;
    for (const option of command.options) {
      option.mandatory = false;
    }
    command.allowUnknownOption(true).allowExcessArguments(true);
    const commandPath = `uip maestro case ${commandName}`;
    const replacement = replacementFor(commandParts);
    command.trackedAction(processContext, async () => {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Code: "DeprecatedCommand",
        ErrorCode: "method_not_allowed",
        Message: `The command "${commandPath}" is deprecated and no longer supported.`,
        Instructions: replacement,
        Retry: "RetryWillNotFix",
        Data: {
          Command: commandPath,
          Replacement: replacement
        }
      });
      processContext.exit(1);
    });
  }
}

